// A view is bound to its OWN chunk buffer: features are never split across
// chunks, so every ring of a feature reads one contiguous typed array.
// Float64 chunks hand back the exact stored doubles (signed zeros included);
// Int32 chunks decode metres on access.
function makeRingView(chunkBuffer, basePair, vertexCount) {
  function pairAt(within, target) {
    var j = (basePair + within) * 2;
    var x, y;
    if (chunkBuffer.ints) { x = chunkBuffer.ints[j] / 1000; y = chunkBuffer.ints[j + 1] / 1000; }
    else { x = chunkBuffer.doubles[j]; y = chunkBuffer.doubles[j + 1]; }
    target[0] = x; target[1] = y;
    return target;
  }
  var target = new Array(vertexCount);
  return new Proxy(target, {
    get: function (t, prop, receiver) {
      if (typeof prop === 'string') {
        var idx = +prop;
        if (Number.isInteger(idx) && idx >= 0 && idx < vertexCount) {
          return pairAt(idx, [0, 0]);
        }
      }
      return Reflect.get(t, prop, receiver);
    }
  });
}

var ASSEMBLE_BATCH = 512;

// Cooperative assembly: metadata records become lazy ring views over the
// single set of per-chunk coordinate buffers. Bounded batches yield to the
// event loop and honour the abort signal, so the full-map assembly can never
// be an unbounded blocking gap and a cancelled load publishes nothing.
async function assembleData(manifest, chunkRecords, opts) {
  opts = opts || {};
  var signal = opts.signal || null;
  var onProgress = opts.onProgress || null;
  var layers = { water: [], buildings: [], roads: [], bridges: [] };
  var featureIndex = 0, cursor = 0, sinceYield = 0;
  var coordBuffers = manifest._coordBuffer.chunks;
  for (var ci = 0; ci < chunkRecords.length; ci++) {
    var doc = chunkRecords[ci];
    if (doc.format !== METADATA_FORMAT) throw FormatError('bad metadata format in chunk ' + ci);
    if (doc.chunk !== ci) throw FormatError('metadata chunk index mismatch ' + ci);
    var chunkMeta = manifest.chunks[ci];
    if (!isInt(doc.pairOffset) || doc.pairOffset !== chunkMeta.pairOffset) {
      throw FormatError('metadata pairOffset disagrees with manifest for chunk ' + ci);
    }
    var chunkBuffer = coordBuffers[ci];
    if (!chunkBuffer || chunkBuffer.ordinateBytes !== chunkMeta._ordinateBytes) {
      throw FormatError('coordinate buffer missing for chunk ' + ci);
    }
    var recs = doc.features;
    if (!Array.isArray(recs) || recs.length !== chunkMeta.features) {
      throw FormatError('metadata feature count disagrees with manifest for chunk ' + ci);
    }
    for (var fi = 0; fi < recs.length; fi++) {
      var rec = recs[fi];
      var verts = validateFeatureRecord(rec, 'feature ' + (rec && rec.id || featureIndex), cursor, manifest.pairCount);
      var chunkLocalOffset = rec.o - chunkMeta.pairOffset;
      var ringCursor = 0;
      var polygons = rec.g.map(function (ringCounts) {
        return ringCounts.map(function (n) {
          var base = chunkLocalOffset + ringCursor;
          ringCursor += n;
          return makeRingView(chunkBuffer, base, n);
        });
      });
      if (ringCursor !== verts) throw FormatError('feature ' + rec.id + ': ring counts inconsistent');
      var feature = {
        id: rec.id,
        sourceId: rec.s,
        localId: rec.u,
        properties: rec.p,
        polygons: polygons,
        bounds: rec.b
      };
      layers[LAYER_NAMES[rec.l]].push(feature);
      cursor += verts;
      featureIndex++;
      sinceYield++;
      if (sinceYield >= ASSEMBLE_BATCH) {
        sinceYield = 0;
        if (signal && signal.aborted) throw abortError();
        if (onProgress) onProgress({ phase: 'assemble', loaded: featureIndex, total: manifest.featureCount });
        await tick();
        if (signal && signal.aborted) throw abortError();
