// --------------------------------------------------------------------------
// Geometry hash: canonical little-endian Float64 of every ordinate in
// flatten order, independent of the storage encoding. The work is
// incremental and cooperative (bounded blocks, event-loop yields, abort
// checks) so the full-map 184 MiB verification cannot be one long task.
// Float64 chunks hash their stored bytes directly -- the on-disk little
// endian doubles ARE the canonical bytes, so there is never a second full
// Float64 materialization. Int32 chunks decode into one reused 128 KiB
// scratch block. Per-chunk encodings are hashed in chunk/pair order, which
// is the same flatten order the packer hashed over.
// --------------------------------------------------------------------------

function hostIsLittleEndian() {
  var b = new ArrayBuffer(8);
  new Float64Array(b)[0] = 1;
  return new Uint8Array(b)[0] === 0 && new Uint8Array(b)[7] === 0x3f;
}

var HASH_BLOCK_PAIRS = 8192;       // 128 KiB of decoded doubles per block
var HASH_BYTE_BLOCK = 65536;       // 64 KiB of stored f64 bytes per block
var HASH_YIELD_BLOCKS = 4;         // yield roughly every 256-512 KiB

async function computeGeometrySha(manifest, opts) {
  opts = opts || {};
  var signal = opts.signal || null;
  var onProgress = opts.onProgress || null;
  if (!hostIsLittleEndian()) throw FormatError('big-endian hosts are not supported');
  var hash = new Sha256();
  var scratch = new Float64Array(HASH_BLOCK_PAIRS * 2);
  var chunkBuffers = manifest._coordBuffer.chunks;
  var pairsHashed = 0;
  var blocksSinceYield = 0;
  for (var ci = 0; ci < chunkBuffers.length; ci++) {
    if (signal && signal.aborted) throw abortError();
    var cb = chunkBuffers[ci];
    if (cb.ints) {
      var ints = cb.ints;
      for (var p = 0; p < ints.length; p += HASH_BLOCK_PAIRS * 2) {
        var n = Math.min(HASH_BLOCK_PAIRS * 2, ints.length - p);
        for (var k = 0; k < n; k++) {
          var v = ints[p + k] / 1000;
          if (!isFinite(v)) throw FormatError('non-finite decoded ordinate');
          scratch[k] = v;
        }
        hash.update(new Uint8Array(scratch.buffer, 0, n * 8));
        blocksSinceYield++;
        if (blocksSinceYield >= HASH_YIELD_BLOCKS) {
          blocksSinceYield = 0;
          if (onProgress) {
            onProgress({ phase: 'verify-geometry', loaded: pairsHashed, total: manifest.pairCount });
          }
          await tick();
          if (signal && signal.aborted) throw abortError();
        }
      }
    } else {
      var doubles = cb.doubles;
      for (var off = 0; off < doubles.length; off += HASH_BYTE_BLOCK / 8) {
        var end = Math.min(doubles.length, off + HASH_BYTE_BLOCK / 8);
        for (var d = off; d < end; d++) {
          if (!isFinite(doubles[d])) throw FormatError('non-finite decoded ordinate');
        }
        hash.update(new Uint8Array(cb.buffer, off * 8, (end - off) * 8));
        blocksSinceYield++;
        if (blocksSinceYield >= HASH_YIELD_BLOCKS) {
          blocksSinceYield = 0;
          if (onProgress) {
            onProgress({ phase: 'verify-geometry', loaded: pairsHashed, total: manifest.pairCount });
          }
          await tick();
          if (signal && signal.aborted) throw abortError();
        }
      }
    }
    pairsHashed += manifest.chunks[ci].pairCount;
    if (onProgress) {
      onProgress({ phase: 'verify-geometry', loaded: pairsHashed, total: manifest.pairCount });
    }
    await tick();
    if (signal && signal.aborted) throw abortError();
  }
  if (pairsHashed !== manifest.pairCount) {
    throw FormatError('geometry hash covered ' + pairsHashed + ' of ' + manifest.pairCount + ' pairs');
  }
  return hash.hex();
}
